const mastersRio=new Image();mastersRio.src='assets/chefes-master-rio.png?v=20261020-6';
const localEnemies=new Map();
function localEnemyImage(id,appearance='regional'){const {src}=enemyWardrobe(id,appearance);return sceneImage(localEnemies,src,()=>{const img=new Image();img.src=src;return img},4)}
const neighborhoodImages=new Map();let previewStage=0;
function neighborhoodImage(index){const stage=stages[index];return sceneImage(neighborhoodImages,stage.id,()=>{const img=new Image();img.src=stage.image;return img},2)}
export function setNeighborhood(index){previewStage=index;neighborhoodImage(index);localEnemyImage(stages[index].id);localEnemyImage(stages[index].id,'light')}
setNeighborhood(0);
export {portrait} from './realistic-art.js';
function ellipse(c,x,y,rx,ry,color){c.fillStyle=color;c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fill()}
export function drawStreet(c,run,t,reduced=false){const camera=run?.camera||0,stage=run?.stageIndex??previewStage,streetMode=run?!run.arenaMission:getArena()==='streets',place=stages[stage],background=neighborhoodImage(stage);if(run&&stage<stages.length-1){neighborhoodImage(stage+1);localEnemyImage(stages[stage+1].id);localEnemyImage(stages[stage+1].id,'light')}c.fillStyle='#091622';c.fillRect(0,0,1280,620);if(!streetMode){drawStage(c,t,run?.arenaId||getArena())}else if(background.complete&&background.naturalWidth){for(let i=0;i<3;i++)c.drawImage(background,i*1860-camera,0,1860,620)}else if(street.complete&&street.naturalWidth){for(let i=0;i<3;i++)c.drawImage(street,i*1860-camera,0,1860,620)}else{c.fillStyle='#142b34';c.fillRect(0,0,1280,400);c.fillStyle='#19232b';c.fillRect(0,400,1280,220)}const shade=c.createLinearGradient(0,0,0,620);shade.addColorStop(0,'#030918b8');shade.addColorStop(.28,'#06121c00');shade.addColorStop(1,'#040a1455');c.fillStyle=shade;c.fillRect(0,0,1280,620);
 if(!reduced&&streetMode&&place.weather==='rain'){c.strokeStyle='#afcde51a';c.lineWidth=1;for(let i=0;i<65;i++){const x=((i*139+t*105-camera*.4)%1400+1400)%1400-50,y=(i*97+t*550)%620;c.beginPath();c.moveTo(x,y);c.lineTo(x-7,y+20);c.stroke()}}
 c.save();c.translate(-camera,0);if(streetMode){for(const sx of [1060,2450]){c.fillStyle='#445052';c.fillRect(sx-3,305,7,120);c.fillStyle='#153936';c.fillRect(sx-155,285,310,62);c.strokeStyle='#bec6a4';c.lineWidth=2;c.strokeRect(sx-155,285,310,62);c.fillStyle='#f6eedb';c.font='700 21px Arial';c.textAlign='center';c.fillText(place.name,sx,313,290);c.font='11px Arial';c.fillText(`${place.city.toUpperCase()} / ${place.uf} · ${place.region.toUpperCase()}`,sx,333)}}for(let x=100;x<3400;x+=350){c.fillStyle='#e8b76b24';c.fillRect(x,600,105,4)}if(run){for(const o of run.objects)drawObject(c,o);for(const q of run.pickups){c.save();c.translate(q.x,q.lane);ellipse(c,0,3,27,9,'#0007');c.shadowBlur=18;c.shadowColor=q.kind==='food'?'#b6e881':'#ffa955';ellipse(c,0,-16+Math.sin(t*5)*3,20,20,'#182c30');c.shadowBlur=0;c.strokeStyle=q.kind==='food'?'#c3e8a0':'#ffa955';c.lineWidth=2;c.stroke();c.fillStyle=c.strokeStyle;c.textAlign='center';c.font='bold 20px Arial';c.fillText(q.kind==='food'?'+':'ϟ',0,-9+Math.sin(t*5)*3);c.restore()}}
 c.restore();}
function drawObject(c,o){c.save();c.translate(o.x,o.lane);ellipse(c,0,3,34,9,'#0008');if(o.broken){c.fillStyle='#77634b';c.rotate(.12);for(let i=0;i<5;i++)c.fillRect(i*12-30,-(i%2)*6,24,5);c.restore();return}if(o.kind==='barrel'){const g=c.createLinearGradient(-26,0,26,0);g.addColorStop(0,'#3b4a43');g.addColorStop(.4,'#667666');g.addColorStop(1,'#243b36');c.fillStyle=g;c.fillRect(-26,-72,52,69);ellipse(c,0,-72,26,7,'#7a8271');c.fillStyle='#192c28';c.fillRect(-28,-55,56,5);c.fillRect(-28,-18,56,5);c.fillStyle='#dbaa5777';c.fillRect(-17,-48,34,25);c.font='bold 9px Arial';c.fillStyle='#242c28';c.textAlign='center';c.fillText('BRASA',0,-32)}else{c.fillStyle='#765431';c.fillRect(-31,-58,62,57);c.strokeStyle='#b48a53';c.lineWidth=4;c.strokeRect(-29,-56,58,53);c.beginPath();c.moveTo(-29,-56);c.lineTo(29,-3);c.moveTo(29,-56);c.lineTo(-29,-3);c.stroke()}c.restore()}
export function drawHero(c,p,image,t,camera){if(p.dead&&p.respawn===0)return;if(!reducedMotion()&&p.invincible>0&&Math.floor(t*13)%2===0&&!p.attackTime)return;const scale=.68*streetScale(p.lane);c.save();c.translate(p.x-camera,p.lane);c.scale(scale,scale);drawFighter(c,{...p,x:0,y:p.y/scale,index:p.index,dead:p.dead},image,t,STREET_BODY_HEIGHT/.68); // renderer's origin uses a 510px floor
 c.restore();}
// Keep the existing, source-anchored fighter sheets; move their local floor to zero.
export function hero(c,p,image,t,camera){c.save();const scale=.68*streetScale(p.lane);c.translate(0,-510*scale);drawHero(c,p,image,t,camera);c.restore();if(!p.dead){c.save();c.font='700 11px Arial';c.textAlign='center';c.fillStyle=p.index?'#c6e68c':'#ffb267';c.fillText((p.index+1)+'P',p.x-camera,p.lane+22);c.restore()}}
export function drawEnemy(c,e,t,camera){if(e.dead&&!e.deathTime)return;if(e.bossIdentity&&drawRegionalBoss(c,e,t,camera))return;const regional=localEnemyImage(e.neighborhoodId),variant=localEnemyImage(e.neighborhoodId,e.appearance),enemyAtlas=variant.complete&&variant.naturalWidth?variant:regional.complete&&regional.naturalWidth?regional:enemies,layout=enemyAtlas===variant?enemyWardrobe(e.neighborhoodId,e.appearance).layout:null;const boss=e.enemyType==='boss',heavy=e.enemyType==='heavy',s=enemySize(e.enemyType)*streetScale(e.lane);c.save();c.translate(e.x-camera,e.lane);ellipse(c,0,1,boss?52:37,6,'#00000018');c.scale(e.facing*s,s);if(enemyAtlas.complete&&enemyAtlas.naturalWidth){const col=e.appearance==='light'||e.neighborhoodId?e.spriteColumn:{street:0,runner:1,heavy:2,boss:3}[e.enemyType],row=attackMotion(e).frame>0?1:0,sw=enemyAtlas.naturalWidth/4,sh=enemyAtlas.naturalHeight/2;if(e.dead){c.globalAlpha=Math.min(1,e.deathTime*2)}const pose=atlasPose(enemyAtlas,4,2,col,row,layout),h=spriteHeight(pose.meta);drawFootContacts(c,e,pose.meta,h);c.translate(0,-e.y);if(e.dead){const contact=fallContact(pose.meta,h,fallProgress(e),pose.canvas.width,pose.canvas.height);c.translate(0,contact.y);c.rotate(contact.angle)}skinnedSprite(c,enemyAtlas,0,pose.meta,e,t,h,pose.canvas);faceDamage(c,e,pose.meta,h);if(!e.dead&&e.hp>0&&e.attackTime>0&&!e.attackHit){c.fillStyle='#ffc67d';c.font='bold 25px Arial';c.textAlign='center';c.fillText('!',0,-STREET_BODY_HEIGHT-18)}c.restore();if(!e.dead&&!e.cinematic&&(boss||e.hp<e.maxHp)){c.fillStyle='#09121bc9';c.fillRect(e.x-camera-32,e.lane-(STREET_BODY_HEIGHT+13)*s,64,5);c.fillStyle=boss?'#f7764d':'#d9b46c';c.fillRect(e.x-camera-32,e.lane-(STREET_BODY_HEIGHT+13)*s,64*e.hp/e.maxHp,5)}return}c.scale(STREET_BODY_HEIGHT/214,STREET_BODY_HEIGHT/214);if(e.dead){c.rotate(-1.5);c.translate(72,30);c.globalAlpha=Math.min(1,e.deathTime*2)}else if(e.stun)c.rotate(-.15);const walk=!e.dead&&e.hp>0&&e.vx&&!e.stun?Math.sin(t*10+e.index)*14:0,attack=e.attackTime>0,wind=!e.dead&&e.hp>0&&attack&&!e.attackHit,extend=!e.dead&&e.hp>0&&attack&&e.attackHit;const coat=wind?'#bb795b':e.data.color;
 // Boots, trousers, jacket and a covered face keep street enemies distinct from the roster.
 c.strokeStyle='#101925';c.lineCap='round';c.lineWidth=23;c.beginPath();c.moveTo(-14,-80);c.lineTo(-18+walk,-15);c.lineTo(-8+walk,-8);c.moveTo(13,-80);c.lineTo(20-walk,-14);c.lineTo(31-walk,-7);c.stroke();c.strokeStyle='#354452';c.lineWidth=14;c.beginPath();c.moveTo(-14,-79);c.lineTo(-18+walk,-20);c.moveTo(13,-79);c.lineTo(20-walk,-20);c.stroke();const g=c.createLinearGradient(-35,0,35,0);g.addColorStop(0,'#17222b');g.addColorStop(.55,coat);g.addColorStop(1,'#24313c');c.fillStyle=g;c.beginPath();c.moveTo(-29,-164);c.lineTo(25,-164);c.lineTo(34,-80);c.quadraticCurveTo(0,-68,-32,-81);c.closePath();c.fill();c.strokeStyle='#ffffff25';c.lineWidth=2;c.beginPath();c.moveTo(1,-157);c.lineTo(5,-88);c.stroke();
 c.strokeStyle=coat;c.lineWidth=18;c.beginPath();c.moveTo(-25,-151);c.lineTo(-35,-115);c.lineTo(-10,-100);c.moveTo(24,-151);c.lineTo(extend?67:wind?-7:39,extend?-143:wind?-179:-126);c.lineTo(extend?95:wind?0:58,extend?-143:wind?-186:-145);c.stroke();ellipse(c,extend?95:wind?0:58,extend?-143:wind?-186:-145,11,12,e.appearance==='light'?'#efd0b5':'#b68c6b');ellipse(c,-8,-100,10,11,'#b68c6b');ellipse(c,0,-185,24,29,'#202b36');ellipse(c,5,-184,18,22,e.appearance==='light'?'#e6bea0':'#ae8466');c.fillStyle='#17232c';c.fillRect(-15,-180,39,18);c.fillStyle='#181e28';c.beginPath();c.moveTo(-26,-188);c.quadraticCurveTo(-23,-226,9,-215);c.quadraticCurveTo(31,-213,25,-187);c.closePath();c.fill();c.fillStyle='#dec7a3';c.fillRect(7,-186,5,3);if(boss){c.strokeStyle='#e9c16a';c.lineWidth=3;c.beginPath();c.moveTo(-15,-160);c.quadraticCurveTo(0,-132,18,-160);c.stroke()}
 if(wind){c.fillStyle='#ffbc6c';c.font='bold 27px Arial';c.textAlign='center';c.fillText('!',0,-237)}c.restore();if(!e.dead&&!e.cinematic&&(boss||e.hp<e.maxHp)){c.fillStyle='#09121bc9';c.fillRect(e.x-camera-32,e.lane-(STREET_BODY_HEIGHT+13)*s,64,5);c.fillStyle=boss?'#f7764d':'#d9b46c';c.fillRect(e.x-camera-32,e.lane-(STREET_BODY_HEIGHT+13)*s,64*e.hp/e.maxHp,5)}}
export function drawEffects(c,run){c.save();c.translate(-run.camera,0);for(const d of run.dangers||[]){c.save();c.globalAlpha=.25+Math.sin(run.time*22)*.15;ellipse(c,d.x,d.lane,d.radius,24,d.color);c.strokeStyle=d.color;c.lineWidth=3;c.stroke();c.restore()}for(const p of run.projectiles){c.save();c.shadowColor=p.color;c.shadowBlur=23;ellipse(c,p.x,p.lane-p.y,p.radius,p.radius,p.color);c.fillStyle='#fff2d1';c.font='bold 20px Arial';c.textAlign='center';c.fillText(p.symbol,p.x,p.lane-p.y+7);c.restore()}for(const e of run.effects){c.save();c.translate(e.x,e.lane-e.y);c.globalAlpha=Math.min(1,e.life*5);c.fillStyle=e.color;for(let j=0;j<8;j++){c.rotate(Math.PI/4);c.fillRect(8,0,17+e.life*50,3)}c.restore()}c.restore()}

function drawRegionalBoss(c,e,t,camera){
 const identity=e.bossIdentity,image=identity.master?mastersRio:regionBosses;
 if(!image.complete||!image.naturalWidth)return false;
 c.save();c.translate(e.x-camera,e.lane);ellipse(c,0,1,52,6,'#00000018');if(e.dead){c.globalAlpha=Math.min(1,e.deathTime*2)}
 const scale=enemySize('boss')*streetScale(e.lane);c.scale(scale,scale);c.scale(e.facing,1);
 const sw=image.naturalWidth/(identity.master?2:6),sh=image.naturalHeight/2;
 const col=identity.master?(identity.id==='lula'?0:1):identity.atlasColumn,row=identity.master?(attackMotion(e).frame>0?1:0):identity.atlasRow;
 if(!e.dead&&e.hp>0){if(e.stun)c.rotate(-.1);else if(e.attackTime>0){const action=attackMotion(e);c.rotate(action.impact*.05-action.windup*.035)}}
 const pose=atlasPose(image,identity.master?2:6,2,col,row,identity.master?null:regionalBossLayout),h=spriteHeight(pose.meta);drawFootContacts(c,e,pose.meta,h);c.translate(0,-e.y);if(e.dead){const contact=fallContact(pose.meta,h,fallProgress(e),pose.canvas.width,pose.canvas.height);c.translate(0,contact.y);c.rotate(contact.angle)}skinnedSprite(c,image,0,pose.meta,e,t,h,pose.canvas);faceDamage(c,e,pose.meta,h);
 if(e.shield>0){c.strokeStyle=identity.color;c.lineWidth=3;c.beginPath();c.ellipse(15,-145,65,120,0,0,Math.PI*2);c.stroke()}

 c.restore();if(!e.dead&&!e.cinematic){c.save();const top=e.lane-(STREET_BODY_HEIGHT+13)*scale;c.fillStyle='#0b1721d9';c.fillRect(e.x-camera-60,top,120,7);c.fillStyle=identity.color;c.fillRect(e.x-camera-60,top,120*e.hp/e.maxHp,7);c.font='700 10px Arial';c.textAlign='center';c.fillStyle='#ffe1b2';if(e.attackTime>0&&!e.attackHit){c.font='bold 26px Arial';c.fillText('!',e.x-camera,top-27)}c.restore()}return true;
}
